370	    /**
371	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
372	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
373	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
374	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
375	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
376	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
377	     * written back onto the request so it is what gets stored and returned. Any value that cannot
378	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
379	     * {@code telephone}.
380	     */
381	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
382	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
383	    }
384	
385	    /**
386	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
387	     * (400) naming {@code telephone} when it cannot form a valid number.
388	     */
389	    private static String toE164(String telephone) {
390	        if (telephone == null) {
391	            throw new InvalidOwnerFieldsException(List.of("telephone"));
392	        }
393	        boolean hasCountryCode = telephone.trim().startsWith("+");
394	        String digits = telephone.replaceAll("\\D", "");
395	        String countryCode;
396	        String national;
397	        if (hasCountryCode) {
398	            countryCode = matchCountryCode(digits);
399	            national = digits;
400	        } else {
401	            countryCode = "61";
402	            if (digits.startsWith("0")) {
403	                digits = digits.substring(1);
404	            }
405	            national = "61" + digits;
406	        }
407	        if (!national.matches("[0-9]{8,15}")) {
408	            throw new InvalidOwnerFieldsException(List.of("telephone"));
409	        }
410	        if (countryCode != null) {
411	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
412	            if (requiredLength != null
413	                && national.length() - countryCode.length() != requiredLength) {
414	                throw new InvalidOwnerFieldsException(List.of("telephone"));
415	            }
416	        }
417	        return "+" + national;
418	    }
419	
420	    /**
421	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
422	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
423	     * the number is not length-checked against a country.
424	     */
425	    private static String matchCountryCode(String digits) {
426	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
427	            .filter(digits::startsWith)
428	            .max(Comparator.comparingInt(String::length))
429	            .orElse(null);
430	    }
