432	    /**
433	     * Rejects creating an owner whose derived {@code identityKey} already, in its entirety, belongs
434	     * to another owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' +
435	     * (householdId or empty)}, so it folds the former separate telephone, email and household
436	     * duplicate checks into one: only an exact full-key match is a duplicate. In particular two
437	     * members of the same household (same {@code householdId}) with different telephones have
438	     * different keys and are both allowed. The incoming telephone and email have already been
439	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and the household id has
440	     * been resolved by {@link #resolveHouseholdId}; each existing owner's key is derived the same way
441	     * before comparison. A match results in a 409 response naming {@code identityKey}.
442	     */
443	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
444	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            if (identityKey.equals(existingIdentityKey(existing))) {
447	                throw new DuplicateOwnerIdentityException(identityKey);
448	            }
449	        }
450	    }
451	
452	    /**
453	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
454	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
455	     * are expected to already be in their normalized (E.164, lower-cased) forms.
456	     */
457	    private static String identityKey(String telephone, String email, String householdId) {
458	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
459	    }
460	
461	    /**
462	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
463	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
464	     * the stored email is lower-cased, and the stored household id is used as-is.
465	     */
466	    private static String existingIdentityKey(Owner existing) {
467	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
468	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
469	        return identityKey(telephone, email, existing.getHouseholdId());
470	    }
471	
472	    private static String orEmpty(String value) {
473	        return value == null ? "" : value;
474	    }
475	
476	    /**
477	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
478	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
479	     */
480	    private static String normalizeExisting(String telephone) {
481	        try {
482	            return toE164(telephone);
483	        } catch (InvalidOwnerFieldsException ex) {
484	            return null;
485	        }
486	    }
