609	    /**
610	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
611	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
612	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
613	     * zero-padded sequence equal to one more than the number of owners already in that city
614	     * (e.g. {@code 'SYD-SMI-0007'}).
615	     */
616	    private void assignCustomerCode(Owner owner) {
617	        String city = owner.getCity();
618	        String lastName = owner.getLastName();
619	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
620	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
621	        int sequence = 1;
622	        for (Owner existing : this.clinicService.findAllOwners()) {
623	            if (city.equalsIgnoreCase(existing.getCity())) {
624	                sequence++;
625	            }
626	        }
627	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
628	    }
